    "id": "derivations",
    "title": "Calculations step by step",
    "intro": "Derivations aligned on the equals sign: a pendulum's period, the work–energy theorem, the harmonic oscillator, escape velocity and a relativistic expansion, with mathtools' \\Aboxed, \\MoveEqLeft and \\shortvdotswithin.",
    "rows": [
      {
        "name": "",
        "caption": "Period of a pendulum for small angles, step by step (physics \\qq, \\abs, mathtools \\Aboxed)",
        "locale": "en",
        "input": "latex",
        "options": {},
        "tex": "\\begin{aligned} m L \\ddot{\\theta} &= -m g \\sin\\theta \\\\ \\ddot{\\theta} &\\approx -\\frac{g}{L}\\, \\theta \\qq{for} \\abs{\\theta} \\ll 1 \\\\ \\theta(t) &= \\theta_0 \\cos(\\omega t + \\varphi), \\qquad \\omega = \\sqrt{\\frac{g}{L}} \\\\ \\Aboxed{T &= \\frac{2\\pi}{\\omega} = 2\\pi \\sqrt{\\frac{L}{g}}} \\end{aligned}"
      },
      {
        "name": "",
        "caption": "Work–energy theorem by integrating F dx, the substituted term in color (xcolor \\definecolor, \\boxed)",
        "locale": "en",
        "input": "latex",
        "options": {},
        "tex": "\\definecolor{step}{HTML}{C2410C} \\begin{aligned} W &= \\int_{x_1}^{x_2} F \\dd{x} = \\int_{x_1}^{x_2} m \\dv{v}{t} \\, {\\color{step} \\dd{x}} \\\\ &= \\int_{t_1}^{t_2} m \\dv{v}{t} \\, {\\color{step} v \\dd{t}} = \\int_{v_1}^{v_2} m v \\dd{v} \\\\ &= \\boxed{\\frac{1}{2} m v_2^2 - \\frac{1}{2} m v_1^2} = \\Delta K \\end{aligned}"
      },
      {
        "name": "",
        "caption": "Free harmonic oscillator solved through its characteristic equation, Euler's formula between the last two lines (mathtools \\shortvdotswithin)",
        "locale": "en",
        "input": "latex",
        "options": {},
        "tex": "\\begin{aligned} m \\ddot{x} + k x &= 0, \\qquad x = e^{r t} \\\\ m r^2 + k &= 0 \\quad \\Longrightarrow \\quad r = \\pm i \\omega_0, \\quad \\omega_0 = \\sqrt{k / m} \\\\ x(t) &= C_1 e^{i \\omega_0 t} + C_2 e^{-i \\omega_0 t} \\\\ \\shortvdotswithin{=} &= A \\cos \\omega_0 t + B \\sin \\omega_0 t \\end{aligned}"
      },
      {
        "name": "",
        "caption": "Escape velocity from energy conservation, with a number (mathtools \\Aboxed, physics \\qq, siunitx \\qty)",
        "locale": "en",
        "input": "latex",
        "options": {},
        "tex": "\\begin{aligned} \\frac{1}{2} m v_e^2 - \\frac{G M m}{R} &= 0 \\\\ v_e^2 &= \\frac{2 G M}{R} \\\\ \\Aboxed{v_e &= \\sqrt{\\frac{2 G M}{R}}} \\\\ &\\approx \\qty{11.2}{\\kilo\\meter\\per\\second} \\qq{for the Earth} \\end{aligned}"
      },
      {
        "name": "",
        "caption": "Relativistic energy expanded at low speed (mathtools \\MoveEqLeft)",
        "locale": "en",
        "input": "latex",
        "options": {},
        "tex": "\\begin{aligned} \\MoveEqLeft E = \\gamma m c^2 = \\frac{m c^2}{\\sqrt{1 - v^2 / c^2}} \\\\ &= m c^2 \\left( 1 + \\frac{1}{2} \\frac{v^2}{c^2} + \\frac{3}{8} \\frac{v^4}{c^4} + \\cdots \\right) \\\\ &= m c^2 + \\frac{1}{2} m v^2 + \\frac{3}{8} \\frac{m v^4}{c^2} + \\cdots \\end{aligned}"
      }
    ]
